/**
 * @public
 */
export type FunnelTrapezoidItem = Omit<TrapezoidProps, 'fill'> &
  TrapezoidViewBox & {
    /**
     * The color of the entry. A fill object in the props paints the entry with its definition.
     */
    fill?: string;
    value?: number | string;
    payload?: any;
    tooltipPosition: Coordinate;
    name: string;
    labelViewBox: TrapezoidViewBox;
    parentViewBox: CartesianViewBoxRequired;
    val: number | ReadonlyArray<number>;
    tooltipPayload: TooltipPayload;
  };

/**
 * Internal props, combination of external props + defaultProps + private Recharts state
 */
type InternalFunnelProps = RequiresDefaultProps<StringFillFunnelProps, typeof defaultFunnelProps> & {
  id: GraphicalItemId;
  trapezoids: ReadonlyArray<FunnelTrapezoidItem>;
  /**
   * `url(#…)` of the fill definition of each trapezoid, by index. Undefined for trapezoids with a plain color.
   */
  trapezoidPaintFills?: ReadonlyArray<string | undefined>;
  /**
   * Theme styles of the active shape for each index, without the ones that explicit props override.
   * Empty when there is no active theme.
   */
  indexedActiveStyles?: ReadonlyArray<ColorStyles2D | undefined>;
};

/**
 * External props, intended for end users to fill in
 *
 * The type is exported only so that TypeScript can name it in the declaration files of projects
 * that wrap Recharts components. It is not part of the public API and may change in any release.
 *
 * @internal
 */
export interface FunnelProps<DataPointType = any, DataValueType = any>
  extends DataProvider<DataPointType>, Required<DataConsumer<DataPointType, DataValueType>> {
  /**
   * The fill of the trapezoids. Either a color string, or a {@link RechartsFill} object with an SVG definition,
   * such as a pattern or a gradient.
   *
   * Each trapezoid can have its own fill too: set `fill` in its data entry, to a color or to a fill object.
   * The data entry wins over this prop, and both win over the theme.
   *
   * With a fill object, Recharts renders the definition with a unique ID for each trapezoid,
   * in the chart and in the Legend icons. Tooltip and labels use the solid `color` of the fill object.
   * If the fill object has no `color`, the trapezoids keep the theme colors and the definition gets the theme color.
   *
   * @example <Funnel dataKey="value" fill={{ definition: pattern(patterns.diagonal) }} />
   */
  fill?: string | RechartsFill;
  /**
   * This component is rendered when this graphical item is activated
   * (could be by mouse hover, touch, keyboard, programmatically).
   */
  activeShape?: ActiveShape<FunnelTrapezoidItem, SVGPathElement>;
  /**
   * Specifies when the animation should begin, the unit of this option is ms.
   * @defaultValue 400
   */
  animationBegin?: number;
  /**
   * Specifies the duration of animation, the unit of this option is ms.
   * @defaultValue 1500
   */
  animationDuration?: AnimationDuration;
  /**
   * The type of easing function.
   * @defaultValue ease
   */
  animationEasing?: EasingInput;
  /**
   * Custom animation function for interpolating data items.
   * When provided, this replaces the default animation interpolation.
   *
   * @param prevItems The items from the previous animation frame, or null on first render
   * @param nextItems The target items to animate towards
   * @param animationElapsedTime A normalized time value (0 = start, 1 = end)
   * @returns The interpolated items at time animationElapsedTime
   *
   * @since 3.9
   * @see {@link https://recharts.github.io/en-US/guide/animations/ Animations guide}
   */
  animationInterpolateFn?: AnimationInterpolateFn<FunnelTrapezoidItem, CartesianLayout>;
  /**
   * Strategy for matching previous items to next items during animation.
   * Determines how Recharts pairs old data points with new data points
   * to create smooth transitions.
   *
   * - `matchAppend` (default): match sequentially by index and treat newly appended items as new
   * - `matchByIndex`: match by array position with proportional stretching
   * - `matchByDataKey('someKey')`: match by a data key from the payload
   * - Custom function `(item, index) => key`: match by the returned key
   *
   * @defaultValue append
   * @see matchByIndex
   * @see matchByDataKey
   * @see matchAppend
   *
   * @since 3.9
   * @see {@link https://recharts.github.io/en-US/guide/animations/ Animations guide}
   */
  animationMatchBy?: AnimationMatchByProp<FunnelTrapezoidItem>;
  className?: string;
  /**
   * Hides the whole graphical element when true.
   *
   * Hiding an element is different from removing it from the chart:
   * Hidden graphical elements are still visible in Legend,
   * and can be included in axis domain calculations,
   * depending on `includeHidden` props of your XAxis/YAxis.
   *
   * @defaultValue false
   */
  hide?: boolean;
  /**
   * Unique identifier of this component.
   * Used as an HTML attribute `id`, and also to identify this element internally.
   *
   * If undefined, Recharts will generate a unique ID automatically.
   */
  id?: string;
  /**
   * If set false, animation of funnel will be disabled.
   * If set "auto", the animation will be disabled in SSR and will respect the user's prefers-reduced-motion system preference for accessibility.
   * @defaultValue auto
   */
  isAnimationActive?: boolean | 'auto';
  label?: ImplicitLabelListType;
  /**
   * @defaultValue triangle
   */
  lastShapeType?: 'triangle' | 'rectangle';
  /**
   * The type of icon in legend.  If set to 'none', no legend item will be rendered.
   * @defaultValue rect
   */
  legendType?: LegendType;
  /**
   * Name represents each sector in the tooltip.
   * This allows you to extract the name from the data:
   *
   * - `string`: the name of the field in the data object;
   * - `number`: the index of the field in the data;
   * - `function`: a function that receives the data object and returns the name.
   *
   * @defaultValue name
   */
  nameKey?: DataKey<DataPointType, DataValueType>;
  /**
   * The customized event handler of animation end
   */
  onAnimationEnd?: () => void;
  /**
   * The customized event handler of animation start
   */
  onAnimationStart?: () => void;
  reversed?: boolean;
  /**
   * If set a ReactElement, the shape of funnel can be customized.
   * If set a function, the function will be called to render customized shape.
   * During animations, the function shape also receives `animationElapsedTime`, `isAnimating`, and `isEntrance`.
   * By default, renders a trapezoid.
   */
  shape?: ActiveShape<FunnelTrapezoidItem & ShapeAnimationProps, SVGPathElement>;
  tooltipType?: TooltipType;
  /**
   * Formats the value displayed in the tooltip for this Funnel.
   * When set, takes precedence over the `formatter` prop on the Tooltip component.
   */
  formatter?: Formatter;
  /**
   * The customized event handler of click on the area in this group
   */
  onClick?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;
  /**
   * The customized event handler of mousedown on the area in this group
   */
  onMouseDown?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;
  /**
   * The customized event handler of mouseup on the area in this group
   */
  onMouseUp?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;
  /**
   * The customized event handler of mousemove on the area in this group
   */
  onMouseMove?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;
  /**
   * The customized event handler of mouseover on the area in this group
   */
  onMouseOver?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;
  /**
   * The customized event handler of mouseout on the area in this group
   */
  onMouseOut?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;
  /**
   * The customized event handler of mouseenter on the area in this group
   */
  onMouseEnter?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;
  /**
   * The customized event handler of mouseleave on the area in this group
   */
  onMouseLeave?: (data: FunnelTrapezoidItem, index: number, e: React.MouseEvent<SVGPathElement>) => void;
}

type FunnelSvgProps = Omit<PresentationAttributesAdaptChildEvent<FunnelTrapezoidItem, SVGPathElement>, 'ref' | 'fill'>;

/**
 * Props after the fill object is split off: `fill` is the base color.
 */
type StringFillFunnelProps = Omit<FunnelProps, 'fill'> & { fill?: string };
type StringFillProps = Omit<Props, 'fill'> & { fill?: string };

type InternalProps = FunnelSvgProps & InternalFunnelProps;

/**
 * @public
 */
export type Props<DataPointType = any, DataValueType = any> = FunnelSvgProps &
  FunnelProps<DataPointType, DataValueType>;

type RealFunnelData = unknown;

type FunnelTrapezoidsProps = ShapeAnimationProps & {
  trapezoids: ReadonlyArray<FunnelTrapezoidItem>;
  allOtherFunnelProps: InternalProps;
};

/**
 * The color a trapezoid is rendered with: its fill, or its stroke when there is no fill.
 * Tooltip and Legend both report this so they always match the chart.
 */
export function getFunnelEntryColor(entry: unknown): string | undefined {
  if (entry != null && typeof entry === 'object') {
    if ('fill' in entry && typeof entry.fill === 'string') {
      return entry.fill;
    }
    if ('stroke' in entry && typeof entry.stroke === 'string') {
      return entry.stroke;
    }
  }
  return undefined;
}

const SetFunnelTooltipEntrySettings = React.memo(
  ({
    dataKey,
    nameKey,
    stroke,
    strokeWidth,
    fill,
    name,
    hide,
    tooltipType,
    formatter,
    trapezoids,
    id,
  }: Pick<
    InternalProps,
    'dataKey' | 'nameKey' | 'stroke' | 'strokeWidth' | 'fill' | 'name' | 'hide' | 'tooltipType' | 'formatter' | 'id'
  > & {
    trapezoids: ReadonlyArray<FunnelTrapezoidItem>;
  }) => {
    const tooltipEntrySettings: TooltipPayloadConfiguration = {
      /*
       * Per-item tooltip payloads, like Pie: each trapezoid carries its resolved color so
       * the tooltip item matches the chart. An explicit `name` prop still overrides the
       * per-entry names, as it did before.
       */
      dataDefinedOnItem: trapezoids.map(trapezoid =>
        /*
         * An explicit `name` prop overrides per-entry names, but only for entries whose
         * datum does not provide a name through nameKey - datum names always win.
         */
        name == null
          ? trapezoid.tooltipPayload
          : trapezoid.tooltipPayload.map(item =>
              getValueByDataKey(item.payload, nameKey) != null ? item : { ...item, name },
            ),
      ),
      getPosition: index => trapezoids[Number(index)]?.tooltipPosition,
      settings: {
        stroke,
        strokeWidth,
        fill,
        dataKey,
        name,
        nameKey,
        hide,
        type: tooltipType,
        color: fill,
        unit: '', // Funnel does not have unit, why?
        formatter,
        graphicalItemId: id,
      },
    };
    return <SetTooltipEntrySettings tooltipEntrySettings={tooltipEntrySettings} />;
  },
);

function SetFunnelPayloadLegend({
  funnelSettings,
  fillObjects,
}: {
  funnelSettings: ResolvedFunnelSettings;
  /**
   * The fill object of each trapezoid, by index.
   */
  fillObjects: ReadonlyArray<RechartsFill | undefined>;
}) {
  const legendPayload = useAppSelector(state => selectFunnelLegend(state, funnelSettings));
  if (legendPayload == null) {
    return null;
  }
  const legendPayloadWithFills = legendPayload.map((entry, index) => {
    const fill = fillObjects[index];
    return fill == null ? entry : { ...entry, fill };
  });
  return <SetLegendPayload legendPayload={legendPayloadWithFills} />;
}

/**
 * Returns the data entry of a trapezoid, as the user wrote it. Undefined for trapezoids made from Cells only.
 * @param trapezoid the trapezoid
 */
function getFunnelDataEntry(trapezoid: FunnelTrapezoidItem): unknown {
  const { payload } = trapezoid;
  return payload != null && typeof payload === 'object' && 'payload' in payload ? payload.payload : undefined;
}

function FunnelLabelListProvider({
  showLabels,
  trapezoids,
  children,
}: {
  showLabels: boolean;
  trapezoids: ReadonlyArray<FunnelTrapezoidItem> | undefined;
  children: ReactNode;
}) {
  const labelListEntries: ReadonlyArray<CartesianLabelListEntry> | undefined = useMemo(() => {
    if (!showLabels) {
      return undefined;
    }
    return trapezoids?.map((entry): CartesianLabelListEntry => {
      const viewBox: TrapezoidViewBox = entry.labelViewBox;

      return {
        ...viewBox,
        value: entry.name,
        payload: entry.payload,
        parentViewBox: entry.parentViewBox,
        viewBox,
        fill: entry.fill,
      };
    });
  }, [showLabels, trapezoids]);

  return <CartesianLabelListContextProvider value={labelListEntries}>{children}</CartesianLabelListContextProvider>;
}

/**
 * Returns what the user styled a trapezoid with: its `Cell` props if they have colors, otherwise its data entry.
 * The trapezoid `payload` already includes the theme colors, so the data entry is the `payload` one level deeper.
 */
function getOwnColorSource(trapezoid: FunnelTrapezoidItem, cellProps: unknown): unknown {
  if (hasOwnColors(cellProps)) {
    return cellProps;
  }
  const { payload } = trapezoid;
  return payload != null && typeof payload === 'object' && 'payload' in payload ? payload.payload : undefined;
}

function FunnelTrapezoids(props: FunnelTrapezoidsProps) {
  const { trapezoids, allOtherFunnelProps, animationElapsedTime, isAnimating, isEntrance } = props;
  const activeItemIndex = useAppSelector(selectActiveTooltipIndex);
  const {
    onMouseEnter: onMouseEnterFromProps,
    onClick: onItemClickFromProps,
    onMouseLeave: onMouseLeaveFromProps,
    shape,
    activeShape,
    indexedActiveStyles,
    ...restOfAllOtherProps
  } = allOtherFunnelProps;
  const cells = findAllByType(allOtherFunnelProps.children, Cell);

  const onMouseEnterFromContext = useMouseEnterItemDispatch(
    onMouseEnterFromProps,
    allOtherFunnelProps.dataKey,
    allOtherFunnelProps.id,
  );
  const onMouseLeaveFromContext = useMouseLeaveItemDispatch(onMouseLeaveFromProps);
  const onClickFromContext = useMouseClickItemDispatch(
    onItemClickFromProps,
    allOtherFunnelProps.dataKey,
    allOtherFunnelProps.id,
  );

  return (
    <>
      {trapezoids.map((entry: FunnelTrapezoidItem, i: number) => {
        const isActiveIndex = Boolean(activeShape) && activeItemIndex === String(i);
        const trapezoidOptions = isActiveIndex ? activeShape : shape;
        const activeStyleOverrides =
          isActiveIndex && indexedActiveStyles != null && indexedActiveStyles.length > 0
            ? getActiveStyleOverrides(
                activeShape,
                indexedActiveStyles[i % indexedActiveStyles.length],
                getOwnColorSource(entry, cells[i]?.props),
              )
            : undefined;
        const { id, ...trapezoidProps }: FunnelTrapezoidProps = {
          ...entry,
          fill: allOtherFunnelProps.trapezoidPaintFills?.[i] ?? entry.fill,
          ...activeStyleOverrides,
          option: trapezoidOptions,
          isActive: isActiveIndex,
          stroke: activeStyleOverrides?.stroke ?? entry.stroke,
          animationElapsedTime,
          isAnimating,
          isEntrance,
        };

        return (
          <Layer
            key={`trapezoid-${i}`}
            className="recharts-funnel-trapezoid"
            {...adaptEventsOfChild(restOfAllOtherProps, entry, i)}
            onMouseEnter={onMouseEnterFromContext(entry, i)}
            onMouseLeave={onMouseLeaveFromContext(entry, i)}
            onClick={onClickFromContext(entry, i)}
          >
            <FunnelTrapezoid {...trapezoidProps} />
          </Layer>
        );
      })}
    </>
  );
}

const defaultFunnelAnimateItems: AnimationInterpolateFn<FunnelTrapezoidItem, CartesianLayout> = (
  items,
  animationElapsedTime,
) => {
  if (items == null) return [];
  if (animationElapsedTime === 1) {
    return items.flatMap(item => (item.status === 'removed' ? [] : [item.next]));
  }
  return items.flatMap(item => {
    if (item.status === 'removed') return [];
    if (item.status === 'matched') {
      return [
        {
          ...item.next,
          x: interpolate(item.prev.x, item.next.x, animationElapsedTime),
          y: interpolate(item.prev.y, item.next.y, animationElapsedTime),
          upperWidth: interpolate(item.prev.upperWidth, item.next.upperWidth, animationElapsedTime),
          lowerWidth: interpolate(item.prev.lowerWidth, item.next.lowerWidth, animationElapsedTime),
          height: interpolate(item.prev.height, item.next.height, animationElapsedTime),
        },
      ];
    }
    // added
    const { next } = item;
    return [
      {
        ...next,
        x: interpolate(next.x + next.upperWidth / 2, next.x, animationElapsedTime),
        y: interpolate(next.y + next.height / 2, next.y, animationElapsedTime),
        upperWidth: interpolate(0, next.upperWidth, animationElapsedTime),
        lowerWidth: interpolate(0, next.lowerWidth, animationElapsedTime),
        height: interpolate(0, next.height, animationElapsedTime),
      },
    ];
  });
};

function TrapezoidsWithAnimation({
  previousTrapezoidsRef,
  props,
}: {
  props: InternalProps;
  previousTrapezoidsRef: MutableRefObject<ReadonlyArray<FunnelTrapezoidItem> | undefined>;
}) {
  const { trapezoids, isAnimationActive, animationBegin, animationDuration, animationEasing, animationInterpolateFn } =
    props;
  const layout = useCartesianChartLayout();

  const { isAnimating, handleAnimationStart, handleAnimationEnd } = useAnimationCallbacks(
    props.onAnimationStart,
    props.onAnimationEnd,
  );

  if (layout == null) return null;

  return (
    <FunnelLabelListProvider showLabels={!isAnimating} trapezoids={trapezoids}>
      <AnimatedItems
        animationInput={trapezoids}
        animationIdPrefix="recharts-funnel-"
        items={trapezoids}
        previousItemsRef={previousTrapezoidsRef}
        isAnimationActive={isAnimationActive}
        animationBegin={animationBegin}
        animationDuration={animationDuration}
        animationEasing={animationEasing}
        onAnimationStart={handleAnimationStart}
        onAnimationEnd={handleAnimationEnd}
        animationInterpolateFn={animationInterpolateFn}
        animationMatchBy={props.animationMatchBy}
        layout={layout}
      >
        {(stepData, animationElapsedTime, isEntrance) => (
          <Layer>
            <FunnelTrapezoids
              trapezoids={stepData}
              allOtherFunnelProps={props}
              animationElapsedTime={animationElapsedTime}
              isAnimating={isAnimating || animationElapsedTime < 1}
              isEntrance={isEntrance}
            />
          </Layer>
        )}
      </AnimatedItems>
      <LabelListFromLabelProp label={props.label} />
      {props.children}
    </FunnelLabelListProvider>
  );
}

function RenderTrapezoids(props: InternalProps) {
  const previousTrapezoidsRef = useRef<ReadonlyArray<FunnelTrapezoidItem> | undefined>(undefined);

  return <TrapezoidsWithAnimation props={props} previousTrapezoidsRef={previousTrapezoidsRef} />;
}

/**
 * Every themeable style key set to undefined.
 * Spreading this first removes the legacy defaults, which never apply together with a theme.
 */
const NO_STYLES: Record<keyof ColorStyles2D, undefined> = {
  fill: undefined,
  fillOpacity: undefined,
  stroke: undefined,
  strokeOpacity: undefined,
  strokeWidth: undefined,
  strokeDasharray: undefined,
};

const getRealWidthHeight = (customWidth: number | string | undefined, offset: ChartOffsetInternal) => {
  const { width, height, left, top } = offset;

  const realWidth: number = getPercentValue(customWidth, width, width);

  return {
    realWidth,
    realHeight: height,
    offsetX: left,
    offsetY: top,
  };
};

export const defaultFunnelProps = {
  animationBegin: 400,
  animationDuration: 1500,
  animationEasing: 'ease',
  animationInterpolateFn: defaultFunnelAnimateItems,
  animationMatchBy: matchAppend,
  fill: '#808080',
  hide: false,
  isAnimationActive: 'auto',
  lastShapeType: 'triangle',
  legendType: 'rect',
  nameKey: 'name',
  reversed: false,
  shape: defaultFunnelShape,
  stroke: '#fff',
} as const satisfies Partial<Props>;

function FunnelImpl(
  props: WithIdRequired<RequiresDefaultProps<StringFillProps, typeof defaultFunnelProps>> & {
    indexedStyles: ReadonlyArray<Record<string, unknown>>;
    unthemedColors: UnthemedColors | undefined;
    indexedActiveStyles: ReadonlyArray<ColorStyles2D | undefined>;
    funnelFillObject: RechartsFill | undefined;
    themeFillObjects: ReadonlyArray<RechartsFill | undefined>;
    hasExplicitColors: boolean;
  },
) {
  const plotArea = usePlotArea();

  const {
    stroke,
    fill,
    legendType,
    hide,
    isAnimationActive,
    animationBegin,
    animationDuration,
    animationEasing,
    nameKey,
    lastShapeType,
    id,
    indexedStyles,
    unthemedColors,
    funnelFillObject,
    themeFillObjects,
    hasExplicitColors,
    ...everythingElse
  } = props;

  const presentationProps = svgPropertiesNoEvents(props);
  const cells = findAllByType(props.children, Cell);

  const funnelSettings: ResolvedFunnelSettings = useMemo(
    () => ({
      dataKey: props.dataKey,
      nameKey,
      data: props.data,
      tooltipType: props.tooltipType,
      lastShapeType,
      reversed: props.reversed,
      customWidth: props.width,
      cells,
      presentationProps,
      indexedStyles,
      unthemedColors,
      legendType: props.legendType,
      id,
    }),
    [
      props.dataKey,
      nameKey,
      props.data,
      props.tooltipType,
      lastShapeType,
      props.reversed,
      props.width,
      cells,
      presentationProps,
      indexedStyles,
      unthemedColors,
      props.legendType,
      id,
    ],
  );

  const trapezoids = useAppSelector(state => selectFunnelTrapezoids(state, funnelSettings));
  const trapezoidFillObjects = (trapezoids ?? []).map((trapezoid, index) =>
    getIndexedEntryFillObject(
      getFunnelDataEntry(trapezoid),
      index,
      funnelFillObject,
      themeFillObjects,
      hasExplicitColors,
    ),
  );

  if (hide || !trapezoids || !trapezoids.length || !plotArea) {
    return null;
  }
  const { height, width } = plotArea;

  const layerClass = clsx('recharts-trapezoids', props.className);

  return (
    <>
      <SetFunnelPayloadLegend funnelSettings={funnelSettings} fillObjects={trapezoidFillObjects} />
      <SetFunnelTooltipEntrySettings
        dataKey={props.dataKey}
        nameKey={props.nameKey}
        stroke={props.stroke}
        strokeWidth={props.strokeWidth}
        fill={props.fill}
        name={props.name}
        hide={props.hide}
        tooltipType={props.tooltipType}
        formatter={props.formatter}
        trapezoids={trapezoids}
        id={id}
      />
      <Layer className={layerClass}>
        {trapezoidFillObjects.some(fillObject => fillObject != null) && (
          <defs>
            {trapezoidFillObjects.map((fillObject, index) =>
              fillObject == null ? null : (
                <FillObjectDefinition
                  // the trapezoid index is the identity of its definition
                  key={index}
                  id={getEntryFillId(id, index)}
                  fillObject={fillObject}
                  color={trapezoids[index]?.fill}
                />
              ),
            )}
          </defs>
        )}
        <RenderTrapezoids
          trapezoidPaintFills={trapezoidFillObjects.map((fillObject, index) =>
            fillObject == null ? undefined : getFillUrl(getEntryFillId(id, index)),
          )}
          {...everythingElse}
          id={id}
          stroke={stroke}
          fill={fill}
          nameKey={nameKey}
          lastShapeType={lastShapeType}
          animationBegin={animationBegin}
          animationDuration={animationDuration}
          animationEasing={animationEasing}
          isAnimationActive={isAnimationActive}
          hide={hide}
          legendType={legendType}
          height={height}
          width={width}
          trapezoids={trapezoids}
        />
      </Layer>
    </>
  );
}

export function computeFunnelTrapezoids({
  dataKey,
  nameKey,
  displayedData,
  tooltipType,
  lastShapeType,
  reversed,
  offset,
  customWidth,
  graphicalItemId,
}: {
  dataKey: Props['dataKey'];
  nameKey: Props['nameKey'];
  offset: ChartOffsetInternal;
  displayedData: ReadonlyArray<RealFunnelData>;
  tooltipType?: TooltipType;
  lastShapeType?: Props['lastShapeType'];
  reversed?: boolean;
  customWidth: number | string | undefined;
  graphicalItemId: GraphicalItemId;
}): ReadonlyArray<FunnelTrapezoidItem> {
  const { realHeight, realWidth, offsetX, offsetY } = getRealWidthHeight(customWidth, offset);
  const values = displayedData.map((entry: unknown) => {
    const val = getValueByDataKey(entry, dataKey, 0);
    return typeof val === 'number' ? val : 0;
  });
  const maxValue = Math.max.apply(null, values);
  const len = displayedData.length;
  const rowHeight = realHeight / len;
  const parentViewBox = { x: offset.left, y: offset.top, width: offset.width, height: offset.height };

  let trapezoids: ReadonlyArray<FunnelTrapezoidItem> = displayedData.map(
    (entry: unknown, i: number): FunnelTrapezoidItem => {
      // getValueByDataKey does not validate the output type
      const rawVal: number | ReadonlyArray<number> = getValueByDataKey(entry, dataKey, 0);
      const name: string = String(getValueByDataKey(entry, nameKey, i));
      let val = rawVal;
      let nextVal: number | ReadonlyArray<number> | undefined;

      if (i !== len - 1) {
        const nextDataValue = getValueByDataKey(displayedData[i + 1], dataKey, 0);
        if (typeof nextDataValue === 'number') {
          nextVal = nextDataValue;
        } else if (Array.isArray(nextDataValue)) {
          const [first, second] = nextDataValue;
          if (typeof first === 'number') {
            val = first;
          }
          if (typeof second === 'number') {
            nextVal = second;
          }
        } else if (nextDataValue === null) {
          nextVal = 0;
        }
      } else if (rawVal instanceof Array && rawVal.length === 2) {
        const [first, second] = rawVal;
        if (typeof first === 'number') {
          val = first;
        }
        if (typeof second === 'number') {
          nextVal = second;
        }
      } else if (lastShapeType === 'rectangle') {
        nextVal = val;
      } else {
        nextVal = 0;
      }

      // @ts-expect-error this is a problem if we have ranged values because `val` can be an array
      const x = maxValue === 0 ? offsetX : ((maxValue - val) * realWidth) / (2 * maxValue) + offsetX;
      const y = rowHeight * i + offsetY;
      // @ts-expect-error getValueByDataKey does not validate the output type
      const upperWidth = maxValue === 0 ? 0 : (val / maxValue) * realWidth;
      // @ts-expect-error nextVal could be an array
      const lowerWidth = maxValue === 0 ? 0 : (nextVal / maxValue) * realWidth;

      const trapezoidColor = getFunnelEntryColor(entry);
      const tooltipPayload: TooltipPayload = [
        {
          name,
          value: val,
          payload: entry,
          dataKey,
          type: tooltipType,
          graphicalItemId,
          ...(trapezoidColor != null ? { color: trapezoidColor, fill: trapezoidColor } : {}),
        },
      ];
      const tooltipPosition: Coordinate = {
        x: x + upperWidth / 2,
        y: y + rowHeight / 2,
      };

      const trapezoidViewBox: TrapezoidViewBox = {
        x,
        y,
        upperWidth,
        lowerWidth,
        width: Math.max(upperWidth, lowerWidth),
        height: rowHeight,
      };

      return {
        ...trapezoidViewBox,
        name,
        val,
        tooltipPayload,
        tooltipPosition,
        ...(entry != null && typeof entry === 'object' ? omit(entry, ['width']) : {}),
        payload: entry,
        parentViewBox,
        labelViewBox: trapezoidViewBox,
      };
    },
  );

  if (reversed) {
    trapezoids = trapezoids.map((entry: FunnelTrapezoidItem, index: number): FunnelTrapezoidItem => {
      const reversedViewBox: TrapezoidViewBox = {
        x: entry.x - (entry.lowerWidth - entry.upperWidth) / 2,
        y: entry.y - index * rowHeight + (len - 1 - index) * rowHeight,
        upperWidth: entry.lowerWidth,
        lowerWidth: entry.upperWidth,
        width: Math.max(entry.lowerWidth, entry.upperWidth),
        height: rowHeight,
      };

      return {
        ...entry,
        ...reversedViewBox,
        tooltipPosition: {
          ...entry.tooltipPosition,
          y: entry.y - index * rowHeight + (len - 1 - index) * rowHeight + rowHeight / 2,
        },
        labelViewBox: reversedViewBox,
      };
    });
  }

  return trapezoids;
}

/**
 * @consumes CartesianViewBoxContext
 * @provides LabelListContext
 * @provides CellReader
 * @consumes RechartsThemeContext
 */
function FunnelFn(propsWithFillObject: Props) {
  const { color: fillColor, fillObject: funnelFillObject } = splitFill(propsWithFillObject.fill);
  // From here on, `fill` is the base color
  const outsideProps: StringFillProps = useMemo(
    () => ({ ...propsWithFillObject, fill: fillColor }),
    [propsWithFillObject, fillColor],
  );
  const theme = useBackwardsCompatibleTheme<Partial<Pick<RechartsTheme, 'graphicalItems'>>>(
    (rechartsTheme: RechartsTheme) => ({ graphicalItems: rechartsTheme.graphicalItems }),
    {},
    undefined,
  );

  /*
   * Funnel is per-index: each trapezoid at index `i` picks its styles from
   * graphicalItems[i % graphicalItems.length].
   * If the Funnel sets its own fill or stroke, it drops the theme fill and stroke together
   * so that its colors are not mixed with the theme colors.
   * Other explicit style props merge with the theme field by field.
   */
  const hasExplicitColors = hasOwnColors(outsideProps);
  const indexedStyles: ReadonlyArray<Record<string, unknown>> = useMemo(() => {
    const graphicalItems = getColorGraphicalItems(theme?.graphicalItems);
    if (graphicalItems == null || graphicalItems.length === 0) {
      return [];
    }
    return graphicalItems.map(style => ({
      // Start without any styles, so that legacy defaults never fill in what the theme leaves out.
      ...NO_STYLES,
      ...getOwnStyles(hasExplicitColors ? withoutColors(style) : style),
      ...getOwnStyles(outsideProps),
    }));
  }, [outsideProps, theme, hasExplicitColors]);
  const unthemedColors = useUnthemedColors(outsideProps);
  /*
   * The active styles are per-index too, same as `indexedStyles`.
   * The theme active colors go with the theme colors, so a Funnel with its own colors drops them too.
   */
  const themeGraphicalItems = getColorGraphicalItems(theme?.graphicalItems);
  const indexedActiveStyles: ReadonlyArray<ColorStyles2D | undefined> = useMemo(
    () => (themeGraphicalItems ?? []).map(style => (hasExplicitColors ? withoutColors(style.active) : style.active)),
    [themeGraphicalItems, hasExplicitColors],
  );

  const resolveLabelTheme = useIndexedLabelThemeResolver(getColorGraphicalItems(theme?.graphicalItems));
  const themeFillObjects = useThemeFillObjects();
  const { id: externalId, ...resolvedProps } = resolveDefaultProps(outsideProps, defaultFunnelProps);
  return (
    <RegisterGraphicalItemId id={externalId} type="funnel">
      {id => (
        <DataLabelThemeContextProvider value={resolveLabelTheme}>
          <DataLabelColorsContextProvider value={filledShapeLabelColors}>
            <FunnelImpl
              {...resolvedProps}
              id={id}
              indexedStyles={indexedStyles}
              unthemedColors={indexedStyles.length > 0 ? unthemedColors : undefined}
              indexedActiveStyles={indexedActiveStyles}
              funnelFillObject={funnelFillObject}
              themeFillObjects={themeFillObjects}
              hasExplicitColors={hasExplicitColors}
            />
          </DataLabelColorsContextProvider>
        </DataLabelThemeContextProvider>
      )}
    </RegisterGraphicalItemId>
  );
}

/**
 * @public
 */
export const Funnel = FunnelFn as {
  <DataPointType = any, DataValueType = any>(outsideProps: Props<DataPointType, DataValueType>): ReactElement;
  (outsideProps: Props<any, any>): ReactElement;
};
// @ts-expect-error we need to set the displayName for debugging purposes
Funnel.displayName = 'Funnel';
