/**
 * Properties needed by custom label renderers that happen to share their names with SVG
 * attributes. Everything else that is a valid SVG property must not leak from a data entry
 * onto the label line or the label text: labels keep the entry color only.
 * https://github.com/recharts/recharts/issues/7974
 */
const LABEL_GEOMETRY_PROP_KEYS = new Set(['cx', 'cy', 'r', 'name']);

function filterEntryPropsForLabels<T extends object>(obj: T): Partial<T> {
  const result: Partial<T> = {};
  for (const key in obj) {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) {
      continue;
    }
    if (key === 'id' || isDataAttribute(key)) {
      continue;
    }
    if (isSvgElementPropKey(key) && !LABEL_GEOMETRY_PROP_KEYS.has(key)) {
      continue;
    }
    result[key] = obj[key];
  }
  return result;
}

interface PieDef {
  /**
   * The x-coordinate of center. If set a percentage, the final value is obtained by multiplying the percentage of container width.
   */
  cx?: number | string;
  /**
   * The y-coordinate of center. If set a percentage, the final value is obtained by multiplying the percentage of container height.
   */
  cy?: number | string;
  /**
   * Angle in degrees from which the chart should start.
   */
  startAngle?: number;
  /**
   * Angle, in degrees, at which the chart should end.
   */
  endAngle?: number;
  /**
   * The angle between two sectors.
   *
   * @example <Pie paddingAngle={5} />
   * @example https://recharts.github.io/examples/PieChartWithPaddingAngle
   */
  paddingAngle?: number;
  /**
   * The inner radius of the sectors.
   * If set a percentage, the final value is obtained by multiplying the percentage of maxRadius which is calculated by the width, height, cx, cy.
   */
  innerRadius?: number | string;
  /**
   * The outer radius of the sectors.
   * If set a percentage, the final value is obtained by multiplying the percentage of maxRadius which is calculated by the width, height, cx, cy.
   * Function should return a string percentage or number.
   */
  outerRadius?: number | string | ((dataPoint: any) => number | string);
  cornerRadius?: number | string;
}

